import{_ as e,H as l,f as a,i as n}from"./chunks/framework.DLd0CbzH.js";const f=JSON.parse('{"title":"Концепция и монетизация — Agelto","description":"","frontmatter":{"type":"concept","tags":["agelto","concept","monetization","market"],"created":"2026-05-31T00:00:00.000Z"},"headers":[],"relativePath":"01_Business/01_Concept_and_Monetization (Agelto).md","filePath":"01_Business/01_Concept_and_Monetization (Agelto).md"}'),i={name:"01_Business/01_Concept_and_Monetization (Agelto).md"};function s(d,t,r,o,g,h){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="концепция-и-монетизация-—-agelto" tabindex="-1">Концепция и монетизация — Agelto <a class="header-anchor" href="#концепция-и-монетизация-—-agelto" aria-label="Permalink to &quot;Концепция и монетизация — Agelto&quot;">​</a></h1><h2 id="проблема" tabindex="-1">Проблема <a class="header-anchor" href="#проблема" aria-label="Permalink to &quot;Проблема&quot;">​</a></h2><p>Строительные сметы в ЕИС содержат детальные спецификации материалов, но:</p><ul><li>85% данных заперты в PDF/Excel без структуры</li><li>Ручной разбор одной сметы — от нескольких часов до 2–3 рабочих дней</li><li>Традиционные агрегаторы (Seldon, Тендерплан) ищут <strong>по названию контракта</strong>, не по составу сметы</li><li>Ежегодный объем строительных контрактов в ЕИС — <strong>&gt;8 трлн ₽</strong></li></ul><p>Поставщик кабеля не знает, есть ли его кабель в смете на «Строительство школы».</p><hr><h2 id="решение-—-концепция-zero-search" tabindex="-1">Решение — концепция Zero-Search <a class="header-anchor" href="#решение-—-концепция-zero-search" aria-label="Permalink to &quot;Решение — концепция Zero-Search&quot;">​</a></h2><p>Менеджеру по продажам не нужно вводить поисковые запросы. Система, зная номенклатуру поставщика (Коллекции), сама находит в тысячах смет именно те строки, которые завод может поставить сегодня.</p><p><strong>5-стадийный конвейер:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ЕИС (zakupki.gov.ru)</span></span>
<span class="line"><span>  └─▶ [1] Агрегация — кроулинг, загрузка документов</span></span>
<span class="line"><span>        └─▶ [2] Парсинг — OCR/AI-декомпозиция PDF и Excel-смет</span></span>
<span class="line"><span>              └─▶ [3] Матчинг — семантическое сопоставление с каталогом поставщика (pgvector)</span></span>
<span class="line"><span>                    └─▶ [4] Скоринг — ранжирование лидов по релевантности</span></span>
<span class="line"><span>                          └─▶ [5] Дистрибуция — доставка лида в CRM (Bitrix24/amoCRM)</span></span></code></pre></div><hr><h2 id="целевая-аудитория-icp" tabindex="-1">Целевая аудитория (ICP) <a class="header-anchor" href="#целевая-аудитория-icp" aria-label="Permalink to &quot;Целевая аудитория (ICP)&quot;">​</a></h2><p><strong>Кто покупает:</strong></p><ul><li>Коммерческий директор / РОП / CDO</li><li>Компании с выручкой от 100 млн ₽/год</li><li>Наличие CRM (amoCRM, Bitrix24, 1С:ERP)</li><li>Выделенный отдел B2B-продаж от 3 менеджеров</li></ul><p><strong>Приоритетные номенклатурные коллекции:</strong></p><ul><li>Заводы ЖБИ</li><li>Кабельно-проводниковая продукция</li><li>Трубный прокат</li><li>Строительная химия и сухие смеси</li></ul><hr><h2 id="рынок-tam-sam-som" tabindex="-1">Рынок (TAM / SAM / SOM) <a class="header-anchor" href="#рынок-tam-sam-som" aria-label="Permalink to &quot;Рынок (TAM / SAM / SOM)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Уровень</th><th style="text-align:left;">База</th><th style="text-align:left;">Оценка</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>TAM</strong></td><td style="text-align:left;">120 000 активных участников ЕИС в стройсекторе</td><td style="text-align:left;">Несколько десятков млрд ₽/год</td></tr><tr><td style="text-align:left;"><strong>SAM</strong></td><td style="text-align:left;">~25 000 средних/крупных компаний (фильтр: выручка ≥100 млн, CRM, отдел продаж)</td><td style="text-align:left;">~15 млрд ₽/год</td></tr><tr><td style="text-align:left;"><strong>SOM</strong></td><td style="text-align:left;">Захват 0.6% SAM за 3 года</td><td style="text-align:left;">90 млн ₽/год</td></tr></tbody></table><hr><h2 id="монетизация" tabindex="-1">Монетизация <a class="header-anchor" href="#монетизация" aria-label="Permalink to &quot;Монетизация&quot;">​</a></h2><h3 id="тарифная-сетка" tabindex="-1">Тарифная сетка <a class="header-anchor" href="#тарифная-сетка" aria-label="Permalink to &quot;Тарифная сетка&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Тариф</th><th style="text-align:left;">Цена</th><th style="text-align:left;">ЦА</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Freemium Light</strong></td><td style="text-align:left;">Бесплатно (ограничен)</td><td style="text-align:left;">Онбординг, триал</td></tr><tr><td style="text-align:left;"><strong>Business</strong></td><td style="text-align:left;">~50 000 ₽/мес · 600 000 ₽/год</td><td style="text-align:left;">Средний бизнес</td></tr><tr><td style="text-align:left;"><strong>Enterprise</strong></td><td style="text-align:left;">Договорная</td><td style="text-align:left;">Крупные холдинги</td></tr></tbody></table><h3 id="unit-экономика" tabindex="-1">Unit-экономика <a class="header-anchor" href="#unit-экономика" aria-label="Permalink to &quot;Unit-экономика&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Метрика</th><th style="text-align:left;">Значение</th></tr></thead><tbody><tr><td style="text-align:left;">ARPU (Business)</td><td style="text-align:left;">600 000 ₽/год</td></tr><tr><td style="text-align:left;">CAC</td><td style="text-align:left;">250 000 ₽</td></tr><tr><td style="text-align:left;">LTV (2 года)</td><td style="text-align:left;">~1 200 000 ₽</td></tr><tr><td style="text-align:left;">LTV/CAC</td><td style="text-align:left;">4.8×</td></tr><tr><td style="text-align:left;">Marketing OPEX</td><td style="text-align:left;">~450 000 ₽/мес</td></tr></tbody></table><h3 id="воронка-продаж-целевые-показатели-мес-12" tabindex="-1">Воронка продаж (целевые показатели, мес. 12) <a class="header-anchor" href="#воронка-продаж-целевые-показатели-мес-12" aria-label="Permalink to &quot;Воронка продаж (целевые показатели, мес. 12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Этап</th><th style="text-align:left;">Канал</th><th style="text-align:left;">CR</th><th style="text-align:left;">Количество/мес</th></tr></thead><tbody><tr><td style="text-align:left;">Посетитель</td><td style="text-align:left;">SEO, Яндекс.Директ</td><td style="text-align:left;">—</td><td style="text-align:left;">~30 000</td></tr><tr><td style="text-align:left;">Лид (MQL)</td><td style="text-align:left;">Вебинар, кейс</td><td style="text-align:left;">3%</td><td style="text-align:left;">~900</td></tr><tr><td style="text-align:left;">Триал (SQL)</td><td style="text-align:left;">Freemium активация</td><td style="text-align:left;">10%</td><td style="text-align:left;">~90</td></tr><tr><td style="text-align:left;">Клиент</td><td style="text-align:left;">Оплата Business/Enterprise</td><td style="text-align:left;">20%</td><td style="text-align:left;">~18</td></tr></tbody></table><hr><h2 id="прогноз-выручки" tabindex="-1">Прогноз выручки <a class="header-anchor" href="#прогноз-выручки" aria-label="Permalink to &quot;Прогноз выручки&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Год</th><th style="text-align:left;">Клиенты</th><th style="text-align:left;">Выручка</th></tr></thead><tbody><tr><td style="text-align:left;">Год 1</td><td style="text-align:left;">30</td><td style="text-align:left;">18 млн ₽</td></tr><tr><td style="text-align:left;">Год 2</td><td style="text-align:left;">70</td><td style="text-align:left;">42 млн ₽</td></tr><tr><td style="text-align:left;">Год 3</td><td style="text-align:left;">150</td><td style="text-align:left;">90 млн ₽</td></tr></tbody></table><p><strong>NPV проекта: 23.3 млн ₽</strong></p><hr><h2 id="синергии" tabindex="-1">Синергии <a class="header-anchor" href="#синергии" aria-label="Permalink to &quot;Синергии&quot;">​</a></h2><ul><li>[[TcenZor]] — общая аудитория: поставщики стройматериалов могут использовать оба продукта</li><li>[[AxiomaErpSdk]] — общие утилиты для работы с API могут быть вынесены в OpenSource-модуль</li></ul>`,34)])])}const y=e(i,[["render",s]]);export{f as __pageData,y as default};
